        row = []
        for c in range(9):
            # Check if outside layer 2 (rows 1-7, cols 1-7) = layer 1 = 8
            if r < 1 or r > 7 or c < 1 or c > 7:
                row.append('8')
            # Check if outside layer 3 (rows 4-6, cols 4-6) = layer 2 = 3
