                val = 8  # Top/bottom rows all 8
            elif r == 1 or r == 5:
                val = 8 if c == 0 or c == 6 else 8  # Actually all 8
            elif r >= 2 and r <= 4:
                if c == 0 or c == 6:
                    val = 8  # Left/right border
