# Last attempt before running out - let me generate full 21x21 with pure concentric rings
# Based on diamond/Manhattan distance from the 7x7 region center

def make_final_predict():
    result = [[0]*21 for _ in range(21)]
    r_off, c_off = 5, 4  # Position based on proportional scaling

    for r in range(21):
        for c in range(21):
            if not (r_off <= r < r_off + 7 and c_off <= c < c_off + 7):
                continue

            rel_r = r - r_off
            rel_c = c - c_off

            # Chebyshev distance from center (0,0 is corner, center is (3,3))
            dist = max(abs(rel_r - 3), abs(rel_c - 3))

            # Pattern: even distance = 8, odd = 3
            if dist % 2 == 0:
                result[r][c] = 8
            else:
                result[r][c] = 3

    return result

